# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { sheetKey, useSheet } from '../sheet/sheet';
import type { Sheet } from '../sheet/sheet';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey, claimsPath } from './claims';
import type { Claim } from './claims';
import { clearSelectedClaims, useSelectedClaims } from './selection';

type BulkSettled = { settled: number; refused: number; claims: Claim[]; lastBatch: number | null };

// Settles the selected claims together as the signed-in user: the server settles each in list order (people in the
// order they were added, newest claim first) by the rules of settling one, counting one sent to PENDING as settled,
// and leaves the rest as they are. Shows how many of each, and the number of the sheet's last batch (a bulk settle
// that settled at least one claim).
function BulkSettle({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const selected = useSelectedClaims(sheet);
  const lastBatch = useSheet(sheet).data?.lastBatch ?? null;
  const settle = useMutation({
    mutationFn: (ids: number[]) =>
      postJson<BulkSettled>(byUser(`${claimsPath(sheet)}/bulk-settle`, user), { claims: ids }),
    onSuccess: (result) => {
      queryClient.setQueryData(claimsKey(sheet), result.claims);
      queryClient.setQueryData<Sheet>(sheetKey(sheet), (old) => (old ? { ...old, lastBatch: result.lastBatch } : old));
      clearSelectedClaims(sheet);
    },
  });
  const act = useSubmitOnce(settle);

  return (
    <p>
      <button type="button" data-testid="bulk-settle" disabled={settle.isPending} onClick={() => act([...selected])}>
        Settle selected
      </button>{' '}
      {lastBatch !== null && 'last batch '}
      <span data-testid="bulk-settle-batch">{lastBatch ?? ''}</span>
      {settle.isSuccess && (
        <>
          {' '}Settled <strong data-testid="bulk-settled">{settle.data.settled}</strong>, refused{' '}
          <strong data-testid="bulk-settle-refused">{settle.data.refused}</strong>
        </>
      )}
      {settle.isError && (
        <span data-testid="bulk-settle-error" role="alert">
          {' '}The bulk settle failed.
        </span>
      )}
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 22, Component: BulkSettle });

